using System;using System.Collections.Generic;using CosmicBlock.Core;using CosmicBlock.UI;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;using UnityEngine.UI;
public static class Sprint6Builder {
 public const string ScenePath="Assets/Scenes/Game.unity";static readonly string[] Paths={"Assets/Art/Planets/Planet01/Planet01_Stage01_Desolate.png","Assets/Art/Planets/Planet01/Planet01_Stage02_Awakening.png","Assets/Art/Planets/Planet01/Planet01_Stage03_Recovering.png","Assets/Art/Planets/Planet01/Planet01_Stage04_Thriving.png","Assets/Art/Planets/Planet01/Planet01_Stage05_Restored.png"};static readonly Color Gold=new Color(1,.78f,.35f,1),Navy=new Color(.025f,.045f,.12f,.88f);
 [MenuItem("COSMIC BLOCK/Sprint 6/Build Planet Restoration")]public static void Build(){ConfigureImports();AssetDatabase.Refresh();var scene=EditorSceneManager.OpenScene(ScenePath);var canvas=GameObject.Find("GameCanvas");var safe=canvas.transform.Find("SafeArea");var hud=UnityEngine.Object.FindAnyObjectByType<GameHud>();if(safe==null||hud==null)throw new Exception("Scene foundation missing.");foreach(var n in new[]{"PlanetRestoration","PlanetEnergyFlight","PlanetCompletion"}){var old=safe.Find(n);if(old!=null)UnityEngine.Object.DestroyImmediate(old.gameObject);}var journey=safe.Find("Journey");if(journey!=null)journey.gameObject.SetActive(false);if(hud.JourneyFeedbackRoot!=null)hud.JourneyFeedbackRoot.SetActive(false);
  var panel=UI("PlanetRestoration",safe);Set(panel,new Vector2(.05f,.735f),new Vector2(.95f,.872f));panel.gameObject.AddComponent<Image>().color=Navy;var root=UI("PlanetVisual",panel);Set(root,new Vector2(.02f,.04f),new Vector2(.30f,.96f));var current=ImageOn(UI("Current",root));Stretch(current.rectTransform);current.preserveAspect=true;current.raycastTarget=false;var next=ImageOn(UI("Next",root));Stretch(next.rectTransform);next.preserveAspect=true;next.raycastTarget=false;next.gameObject.SetActive(false);
  var title=TextOn(UI("Title",panel),"PLANET 01",26,Gold,FontStyle.Bold);Set(title.rectTransform,new Vector2(.32f,.66f),new Vector2(.97f,.96f));var stage=TextOn(UI("Stage",panel),"STAGE 1 · DESOLATE",25,Color.white,FontStyle.Bold);Set(stage.rectTransform,new Vector2(.32f,.39f),new Vector2(.97f,.70f));var energy=TextOn(UI("Energy",panel),"0 / 100 ENERGY",22,Color.white,FontStyle.Bold);Set(energy.rectTransform,new Vector2(.32f,.20f),new Vector2(.97f,.45f));var bar=UI("ProgressBar",panel);Set(bar,new Vector2(.33f,.08f),new Vector2(.96f,.20f));bar.gameObject.AddComponent<Image>().color=new Color(.08f,.12f,.24f,.95f);var fill=ImageOn(UI("Fill",bar));Set(fill.rectTransform,Vector2.zero,new Vector2(0,1));fill.color=Gold;fill.type=Image.Type.Simple;fill.fillAmount=0;fill.raycastTarget=false;var award=UI("EnergyAward",panel);Set(award,new Vector2(.35f,-.10f),new Vector2(.96f,.24f));var awardText=TextOn(award,"+10 ENERGY",27,Gold,FontStyle.Bold);var awardGroup=award.gameObject.AddComponent<CanvasGroup>();awardGroup.alpha=0;award.gameObject.SetActive(false);var sparks=new List<Image>();for(int i=0;i<6;i++){var im=ImageOn(UI("AbsorbSpark_"+i,root));im.rectTransform.anchorMin=im.rectTransform.anchorMax=new Vector2(.5f,.5f);im.rectTransform.sizeDelta=new Vector2(10,10);im.raycastTarget=false;im.gameObject.SetActive(false);sparks.Add(im);}
  var flight=UI("PlanetEnergyFlight",safe);Stretch(flight);var fragments=new List<Image>();for(int i=0;i<12;i++){var im=ImageOn(UI("Fragment_"+i,flight));im.rectTransform.anchorMin=im.rectTransform.anchorMax=new Vector2(.5f,.5f);im.rectTransform.sizeDelta=new Vector2(12,12);im.rectTransform.localRotation=Quaternion.Euler(0,0,45);im.raycastTarget=false;im.gameObject.SetActive(false);fragments.Add(im);}
  var complete=UI("PlanetCompletion",safe);Stretch(complete);complete.gameObject.AddComponent<Image>().color=new Color(.01f,.015f,.06f,.76f);var central=UI("CentralPlanet",complete);Set(central,new Vector2(.22f,.30f),new Vector2(.78f,.72f));var c0=ImageOn(UI("Current",central));Stretch(c0.rectTransform);c0.preserveAspect=true;c0.raycastTarget=false;var c1=ImageOn(UI("Next",central));Stretch(c1.rectTransform);c1.preserveAspect=true;c1.raycastTarget=false;var completeText=TextOn(UI("Text",complete),"PLANET AWAKENING\nSTAGE 2",42,Gold,FontStyle.Bold);Set(completeText.rectTransform,new Vector2(.10f,.16f),new Vector2(.90f,.34f));var completeGroup=complete.gameObject.AddComponent<CanvasGroup>();completeGroup.alpha=0;completeGroup.blocksRaycasts=true;complete.gameObject.SetActive(false);
  var view=panel.gameObject.AddComponent<PlanetRestorationView>();var sprites=new Sprite[5];for(int i=0;i<5;i++)sprites[i]=AssetDatabase.LoadAssetAtPath<Sprite>(Paths[i]);view.Configure(current,next,fill,title,stage,energy,awardText,awardGroup,completeText,completeGroup,root,sparks.ToArray(),sprites,flight,fragments.ToArray(),new[]{c0,c1});hud.ConfigurePlanet(view);
  var staleCombo=GameObject.Find("ComboText");if(staleCombo!=null)UnityEngine.Object.DestroyImmediate(staleCombo);
  foreach(var n in new[]{"PlayingHomeButton","ExitConfirm"}){var oldNav=safe.Find(n);if(oldNav!=null)UnityEngine.Object.DestroyImmediate(oldNav.gameObject);}
  var homeRootNav=safe.Find("HomeRoot");var oldExit=homeRootNav.Find("HomeExitButton");if(oldExit!=null)UnityEngine.Object.DestroyImmediate(oldExit.gameObject);
  var playingHomeRect=UI("PlayingHomeButton",safe);Set(playingHomeRect,new Vector2(.025f,.895f),new Vector2(.13f,.955f));var playingHome=ButtonOn(playingHomeRect,new Color(.03f,.055f,.13f,.84f));var playingHomeLabel=TextOn(UI("Text",playingHomeRect),"HOME",18,new Color(1,.84f,.50f,.95f),FontStyle.Bold);Stretch(playingHomeLabel.rectTransform);
  var exitConfirm=UI("ExitConfirm",safe);Stretch(exitConfirm);exitConfirm.gameObject.AddComponent<Image>().color=new Color(.01f,.015f,.05f,.76f);var confirmCard=UI("Card",exitConfirm);Set(confirmCard,new Vector2(.10f,.38f),new Vector2(.90f,.62f));confirmCard.gameObject.AddComponent<Image>().color=new Color(.025f,.045f,.12f,.98f);var question=TextOn(UI("Question",confirmCard),"게임을 종료하고 홈으로 이동할까요?",29,Color.white,FontStyle.Bold);Set(question.rectTransform,new Vector2(.06f,.52f),new Vector2(.94f,.90f));var keepRect=UI("Continue",confirmCard);Set(keepRect,new Vector2(.08f,.12f),new Vector2(.47f,.43f));var keep=ButtonOn(keepRect,new Color(.12f,.19f,.32f,1));var keepLabel=TextOn(UI("Text",keepRect),"계속하기",24,Color.white,FontStyle.Bold);Stretch(keepLabel.rectTransform);var goRect=UI("GoHome",confirmCard);Set(goRect,new Vector2(.53f,.12f),new Vector2(.92f,.43f));var goHome=ButtonOn(goRect,new Color(.55f,.36f,.12f,1));var goLabel=TextOn(UI("Text",goRect),"홈으로",24,Color.white,FontStyle.Bold);Stretch(goLabel.rectTransform);exitConfirm.gameObject.SetActive(false);
  var exitRect=UI("HomeExitButton",homeRootNav);Set(exitRect,new Vector2(.38f,.025f),new Vector2(.62f,.08f));var homeExit=ButtonOn(exitRect,new Color(.05f,.07f,.12f,.52f));var exitLabel=TextOn(UI("Text",exitRect),"게임 종료",18,new Color(.67f,.70f,.76f,.86f),FontStyle.Normal);Stretch(exitLabel.rectTransform);
  var flow=canvas.GetComponent<GameFlowController>();flow.ConfigureNavigation(playingHome,homeExit,exitConfirm.gameObject,keep,goHome);var roots=new List<GameObject>();foreach(var go in flow.GameRoots)if(go!=null&&go!=journey.gameObject&&go!=hud.JourneyFeedbackRoot&&go.name!="PlanetRestoration"&&go.name!="PlanetEnergyFlight"&&go.name!="PlanetCompletion")roots.Add(go);roots.Add(panel.gameObject);roots.Add(flight.gameObject);roots.Add(complete.gameObject);roots.Add(playingHome.gameObject);var so=new SerializedObject(flow);var prop=so.FindProperty("gameRoots");prop.arraySize=roots.Count;for(int i=0;i<roots.Count;i++)prop.GetArrayElementAtIndex(i).objectReferenceValue=roots[i];so.ApplyModifiedPropertiesWithoutUndo();var home=safe.Find("HomeRoot/PlanetProgress")??safe.Find("HomeRoot/BestJourney");if(home!=null){home.name="PlanetProgress";home.GetComponent<Text>().text="PLANET 01 · STAGE 1 / 0% RESTORED";}var homeRoot=safe.Find("HomeRoot");foreach(var n in new[]{"DevButton","PlanetDebugPanel"}){var oldDev=homeRoot.Find(n);if(oldDev!=null)UnityEngine.Object.DestroyImmediate(oldDev.gameObject);}var oldController=homeRoot.GetComponent<PlanetDebugPanel>();if(oldController!=null)UnityEngine.Object.DestroyImmediate(oldController);var devRect=UI("DevButton",homeRoot);Set(devRect,new Vector2(.86f,.02f),new Vector2(.98f,.075f));var dev=ButtonOn(devRect,new Color(.12f,.15f,.24f,.72f));var devLabel=TextOn(UI("Text",devRect),"DEV",18,new Color(.62f,.68f,.78f,.85f),FontStyle.Bold);Stretch(devLabel.rectTransform);var debugRect=UI("PlanetDebugPanel",homeRoot);Set(debugRect,new Vector2(.53f,.08f),new Vector2(.96f,.43f));debugRect.gameObject.AddComponent<Image>().color=new Color(.02f,.035f,.10f,.97f);var heading=TextOn(UI("Heading",debugRect),"PLANET QA",23,Gold,FontStyle.Bold);Set(heading.rectTransform,new Vector2(.05f,.86f),new Vector2(.80f,.98f));var closeRect=UI("Close",debugRect);Set(closeRect,new Vector2(.82f,.87f),new Vector2(.96f,.98f));var close=ButtonOn(closeRect,new Color(.22f,.16f,.20f,.9f));var closeLabel=TextOn(UI("Text",closeRect),"X",18,Color.white,FontStyle.Bold);Stretch(closeLabel.rectTransform);string[] labels={"RESET PLANET","STAGE 1 TEST · 90","STAGE 2 TEST · 190","STAGE 3 TEST · 290","FINAL TEST · 390"};var presetButtons=new Button[labels.Length];for(int i=0;i<labels.Length;i++){float top=.83f-i*.15f;var br=UI("Preset_"+i,debugRect);Set(br,new Vector2(.08f,top-.12f),new Vector2(.92f,top));presetButtons[i]=ButtonOn(br,new Color(.09f,.13f,.24f,.96f));var label=TextOn(UI("Text",br),labels[i],20,i==4?Gold:Color.white,FontStyle.Bold);Stretch(label.rectTransform);}debugRect.gameObject.SetActive(false);var debugController=homeRoot.gameObject.AddComponent<PlanetDebugPanel>();debugController.Configure(UnityEngine.Object.FindAnyObjectByType<GameSession>(),flow,dev,debugRect.gameObject,close,presetButtons);EditorUtility.SetDirty(debugController);EditorUtility.SetDirty(hud);EditorUtility.SetDirty(view);EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);AssetDatabase.SaveAssets();Validate();Debug.Log("SPRINT65_SCENE_READY");}
 static void ConfigureImports(){foreach(var path in Paths){var ti=AssetImporter.GetAtPath(path)as TextureImporter;if(ti==null)continue;ti.textureType=TextureImporterType.Sprite;ti.spriteImportMode=SpriteImportMode.Single;ti.alphaSource=TextureImporterAlphaSource.FromInput;ti.alphaIsTransparency=true;var st=new TextureImporterSettings();ti.ReadTextureSettings(st);st.spriteMeshType=SpriteMeshType.FullRect;ti.SetTextureSettings(st);ti.filterMode=FilterMode.Bilinear;ti.textureCompression=TextureImporterCompression.CompressedHQ;ti.mipmapEnabled=false;ti.SaveAndReimport();}}
 [MenuItem("COSMIC BLOCK/Sprint 6/Validate")]public static void Validate(){var safe=GameObject.Find("GameCanvas").transform.Find("SafeArea");Require(safe.Find("PlanetRestoration")!=null&&safe.Find("PlanetEnergyFlight")!=null&&safe.Find("PlanetCompletion")!=null,"Planet presentation roots");Require(safe.Find("PlayingHomeButton")!=null&&safe.Find("ExitConfirm")!=null&&safe.Find("HomeRoot/HomeExitButton")!=null,"Sprint 6.6 navigation UI");Require(GameObject.Find("ComboText")==null,"legacy combo HUD removed");Require(UnityEngine.Object.FindObjectsByType<PlanetRestorationView>(FindObjectsInactive.Include).Length==1,"one Planet view");}
 static RectTransform UI(string n,Transform p){var r=new GameObject(n,typeof(RectTransform)).GetComponent<RectTransform>();r.SetParent(p,false);return r;}static Image ImageOn(RectTransform r)=>r.gameObject.AddComponent<Image>();static Button ButtonOn(RectTransform r,Color color){var image=r.gameObject.AddComponent<Image>();image.color=color;var button=r.gameObject.AddComponent<Button>();button.targetGraphic=image;return button;}static Text TextOn(RectTransform r,string v,int z,Color c,FontStyle f){var t=r.gameObject.AddComponent<Text>();t.font=Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");t.text=v;t.fontSize=z;t.fontStyle=f;t.color=c;t.alignment=TextAnchor.MiddleCenter;t.raycastTarget=false;t.resizeTextForBestFit=true;t.resizeTextMinSize=14;t.resizeTextMaxSize=z;return t;}static void Set(RectTransform r,Vector2 a,Vector2 b){r.anchorMin=a;r.anchorMax=b;r.offsetMin=r.offsetMax=Vector2.zero;r.localScale=Vector3.one;}static void Stretch(RectTransform r)=>Set(r,Vector2.zero,Vector2.one);static void Require(bool v,string m){if(!v)throw new Exception("Sprint 6.5 validation failed: "+m);}
